node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });
const tables = db.prepare(\"SELECT name, sql FROM sqlite_master WHERE type='table' ORDER BY name\").all();
let output = '';
for (const t of tables) {
  output += t.sql + ';\n\n';
  const rows = db.prepare('SELECT * FROM [' + t.name + ']').all();
  for (const row of rows) {
    const cols = Object.keys(row);
    const vals = cols.map(c => {
      if (row[c] === null) return 'NULL';
      if (typeof row[c] === 'number') return row[c];
      return \"'\" + String(row[c]).replace(/'/g, \"''\") + \"'\";
    });
    output += 'INSERT INTO [' + t.name + '] (' + cols.join(', ') + ') VALUES (' + vals.join(', ') + ');\n';
  }
  output += '\n';
}
db.close();
require('fs').writeFileSync('/workspace/world_dump.sql', output);
console.log('Dump written to /workspace/world_dump.sql');
console.log('Size: ' + (require('fs').statSync('/workspace/world_dump.sql').size / 1024).toFixed(1) + ' KB');
" 2>&1

